r"""
Write a standalone uv project for one Python version from flat requirements.

The uv counterpart of the Pipenv store: ``docker/env_uv/py<XYZ>/`` holds a
``pyproject.toml`` written by this script and the ``uv.lock`` that
``uv lock`` resolves from it, for exactly one Python version.

WHY NOT LOCK THE REPOSITORY'S OWN pyproject.toml
------------------------------------------------
* ``uv lock`` there resolves every extra for every Python the package
  supports at once (3.8 and up), so one extra that needs 3.10 fails the whole
  lock; and it must build scikit-plots (meson, a C/C++ toolchain) only to
  read its dynamic version.
* A lock per Python version, from the same ``requirements/*.txt`` the Pipenv
  store uses, needs no build and gives each Docker image or CI job the exact
  set for its interpreter.

The project is not a package (``[tool.uv] package = false``): it only names
dependencies. Runtime requirements become ``[project] dependencies`` and dev
requirements the ``dev`` dependency group, which ``uv sync`` installs by
default (``uv sync --no-dev`` leaves it out).

Usage
-----
::

    python flatten_reqs.py requirements/default.txt requirements/all.txt \
        /tmp/flat/runtime.txt /tmp/flat/dev.txt 3.11
    python uv_project_from_reqs.py /tmp/flat/runtime.txt /tmp/flat/dev.txt \
        docker/env_uv/py311 3.11
    uv lock --directory docker/env_uv/py311
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path

__all__ = ["main", "read_requirements", "render_pyproject"]

_VERSION = re.compile(r"^3\.(\d{1,2})$")


def read_requirements(path: Path) -> list[str]:
    """
    Return the requirement lines of a flat requirements file.

    Parameters
    ----------
    path : pathlib.Path
        A file written by ``flatten_reqs.py``: one requirement per line.

    Returns
    -------
    list of str
        Requirements in file order, duplicates removed (first kept); blank
        lines and comments left out.

    Raises
    ------
    ValueError
        If a line is a pip option (``-r``, ``-e``, ``--index-url``...), which
        has no place in ``pyproject.toml``: the flat file should hold none.
    """
    seen: dict[str, None] = {}
    for number, raw in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        line = raw.split(" #", 1)[0].strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("-"):
            raise ValueError(
                f"{path}:{number}: pip option {line!r} cannot go into a "
                "pyproject.toml; flatten the requirements first"
            )
        seen.setdefault(line, None)
    return list(seen)


def render_pyproject(py_version: str, runtime: list[str], dev: list[str]) -> str:
    """
    Return the ``pyproject.toml`` text of the environment for one Python.

    Parameters
    ----------
    py_version : str
        ``"3.X"``; the environment requires exactly that minor version.
    runtime, dev : list of str
        Requirements; dev entries that repeat a runtime entry are left out.

    Returns
    -------
    str
        TOML text, the same for the same inputs.

    Raises
    ------
    ValueError
        If ``py_version`` is not ``3.X``.
    """
    match = _VERSION.match(py_version)
    if not match:
        raise ValueError(f"py_version must look like '3.11', got {py_version!r}")
    tag = f"py3{match.group(1)}"
    dev_only = [r for r in dev if r not in set(runtime)]

    def array(items: list[str]) -> str:
        # json.dumps writes a valid TOML basic string for any requirement.
        body = "".join(f"  {json.dumps(item)},\n" for item in items)
        return f"[\n{body}]"

    return (
        "# Generated by .github/scripts/uv_project_from_reqs.py from\n"
        "# requirements/default.txt and requirements/all.txt; do not edit.\n"
        "# Regenerate with .github/workflows/ci_uv_artifact.yml.\n"
        "[project]\n"
        f'name = "scikit-plots-env-{tag}"\n'
        'version = "0"\n'
        f'requires-python = "=={py_version}.*"\n'
        f"dependencies = {array(runtime)}\n"
        "\n"
        "[dependency-groups]\n"
        f"dev = {array(dev_only)}\n"
        "\n"
        "[tool.uv]\n"
        "package = false\n"
    )


def main(argv: list[str] | None = None) -> int:
    """
    Command line: ``RUNTIME DEV OUT_DIR PY_VERSION``.

    Writes ``OUT_DIR/pyproject.toml``; returns 0, or 2 for wrong arguments.
    """
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 4:  # noqa: PLR2004
        sys.stderr.write(__doc__.split("Usage")[1])
        return 2
    runtime_file, dev_file, out_dir, py_version = args
    text = render_pyproject(
        py_version,
        read_requirements(Path(runtime_file)),
        read_requirements(Path(dev_file)),
    )
    out = Path(out_dir)
    out.mkdir(parents=True, exist_ok=True)
    (out / "pyproject.toml").write_text(text, encoding="utf-8")
    sys.stdout.write(f"wrote {out / 'pyproject.toml'} for Python {py_version}\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
